Author: Yifeng Sun <pkusunyifeng@gmail.com>
Date:   Wed Nov 14 15:14:05 2018 -0800

    oss-fuzz: Fix memory leak in ofctl_parse_flow

    If parse_ofp_flow_mod_str returns no error, ofputil_flow_mod.match
    contains allocated memory that should be free. This patch fixes it.

    Reported-at: https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=11343
    Signed-off-by: Yifeng Sun <pkusunyifeng@gmail.com>
    Signed-off-by: Ben Pfaff <blp@ovn.org>
---
 tests/oss-fuzz/ofctl_parse_target.c | 1 +
 1 file changed, 1 insertion(+)

diff --git a/tests/oss-fuzz/ofctl_parse_target.c b/tests/oss-fuzz/ofctl_parse_target.c
index db86c7da1..d4712a442 100644
--- a/tests/oss-fuzz/ofctl_parse_target.c
+++ b/tests/oss-fuzz/ofctl_parse_target.c
@@ -62,6 +62,7 @@ ofctl_parse_flow(const char *input, int command)
         free(error);
     } else {
         ofctl_parse_flows__(&fm, 1, usable_protocols);
+        minimatch_destroy(&fm.match);
     }
 }
